spec.acceptance_tests:
test("REQ-1: basic target", () => assert.deepEqual(parseLinks("See [[Heart]]"), ["Heart"]));
test("REQ-1: aliases and headings", () => assert.deepEqual(parseLinks("[[Heart#Anatomy|Label]]"), ["Heart"]));
test("REQ-1: code ignored", () => assert.deepEqual(parseLinks("`[[Hidden]]` and ```[[Hidden]]```"), []));

implementation.portable_code:
export function parseLinks(markdown: string): string[] {
  const clean = markdown.replace(/```[\s\S]*?```/g, "").replace(/`[^`]*`/g, "");
  return Array.from(clean.matchAll(/\[\[([^\]]+)\]\]/g), (m) => m[1].split(/[|#]/)[0].trim()).filter(Boolean);
}
